265:
SELECT "j"."preferred_years"
FROM "jobs" AS "j"
WHERE "j"."salary" = (

    SELECT MAX("salary") FROM "jobs"
);

268:
SELECT j."minimum_years"
FROM "jobs" j
WHERE j."salary" = (

    SELECT MAX(j2."salary")
    FROM "jobs" j2
);

280:
SELECT a."name", a."phone"
FROM "applicants" a
JOIN "experiences" e ON e."applicant_id" = a."id"
WHERE e."years_of_experience" = (
    SELECT MIN("years_of_experience") FROM "experiences"
);

